-- 036_chain_menus.sql
-- GENERATED by scripts/chain_menus/build_036.py from supabase/data/chains/*.json - edit the JSON, then re-run the script.
--
-- Official chain menus for franchise branches in 안산 (033/034 imported them with no menu).
-- 15 chains, 742 dishes, all collected on 2026-11-24 from each chain's own website
-- (menu pages, 알레르기 / 원산지 pages). Screenshots of every allergen table: supabase/data/chains/evidence/.
-- With official allergen data (10): BBQ, bhc, 본죽, 버거킹, 프랭크버거, 교촌치킨, 맥도날드, 맘스터치, 페리카나, 써브웨이.
-- Menu only, no allergen data published (5): 굽네치킨, 이삭토스트, KFC, 롯데리아, 엽기떡볶이.
--
-- What this file does: creates two team-only tables (chain_menus, chain_menu_dishes), fills them, and adds
-- apply_chain_menus(). It does NOT touch restaurants or dishes. After reviewing, run:
--     select * from public.apply_chain_menus();            -- every chain with allergen data
--     select * from public.apply_chain_menus('momstouch'); -- one chain
-- apply_chain_menus() copies a chain's dishes to every restaurant whose name_ko matches the chain's
-- name_patterns (ILIKE) and none of its name_exclude, and that has NO dishes yet (real menus are never
-- overwritten). Menu-only chains are refused: empty tags would make every dish look safe.
-- Missing prices are stored as 0 (dishes.price_won is not null) - the app should hide 0원.
-- Undo: delete from public.dishes where id like '%-chain-%';
-- Safe to re-run.

begin;

-- ---------- tables ----------
create table if not exists public.chain_menus (
  chain_id text primary key,                 -- file name, e.g. momstouch
  chain_ko text not null,
  chain_en text not null,
  name_patterns text[] not null,            -- ILIKE patterns for restaurants.name_ko, e.g. '%맘스터치%'
  name_exclude text[] not null default '{}', -- ILIKE patterns that must NOT match (e.g. a kebab shop called BBQ)
  has_allergen_data boolean not null,
  source_urls text[] not null default '{}',
  checked_on date not null,
  notes text not null default ''
);
create table if not exists public.chain_menu_dishes (
  chain_id text not null references public.chain_menus (chain_id) on delete cascade,
  dish_no int not null,
  name_ko text not null,
  name_en text not null,
  price_won int,                             -- null = not shown on the official site
  contains text[] not null default '{}'
    check (contains <@ '{pork,beef,chicken,lamb,seafood,egg,dairy,alcohol,peanut,wheat,soy}'::text[]),
  may_contain text[] not null default '{}'
    check (may_contain <@ '{pork,beef,chicken,lamb,seafood,egg,dairy,alcohol,peanut,wheat,soy}'::text[]),
  allergens_as_written text not null,       -- the official wording, or 'not shown'
  source_url text not null,
  primary key (chain_id, dish_no),
  check (not (contains && may_contain))
);
-- Team only (like 013): RLS on, no policies, so the app cannot read or write these.
alter table public.chain_menus enable row level security;
alter table public.chain_menu_dishes enable row level security;

-- ---------- data ----------
-- Re-running replaces the stored chain data with the current files.
delete from public.chain_menu_dishes;
delete from public.chain_menus;


