-- ---------- apply_chain_menus ----------
create or replace function public.apply_chain_menus(p_chain text default null)
returns table (chain_id text, restaurants_matched int, restaurants_filled int, dishes_added int)
language plpgsql
as $$
#variable_conflict use_column
declare
  c record;
  v_matched int;
  v_filled int;
  v_dishes int;
begin
  if p_chain is not null and not exists (select 1 from public.chain_menus m where m.chain_id = p_chain) then
    raise exception 'unknown chain %', p_chain;
  end if;
  if p_chain is not null and not (select m.has_allergen_data from public.chain_menus m where m.chain_id = p_chain) then
    raise exception 'chain % has no official allergen data; its dishes would all look safe', p_chain;
  end if;

  for c in
    select m.* from public.chain_menus m
    where m.has_allergen_data and (p_chain is null or m.chain_id = p_chain)
    order by m.chain_id
  loop
    create temporary table if not exists _chain_targets (restaurant_id text primary key) on commit drop;
    truncate _chain_targets;

    select r.id from public.restaurants r
    where r.name_ko ilike any (c.name_patterns)
      and not (r.name_ko ilike any (c.name_exclude));
    get diagnostics v_matched = row_count;

    -- keep only restaurants that have no dishes yet
    delete from _chain_targets t where exists (select 1 from public.dishes d where d.restaurant_id = t.restaurant_id);
    select count(*) into v_filled from _chain_targets;

    select t.restaurant_id || '-chain-' || c.chain_id || '-' || cd.dish_no,
           t.restaurant_id, cd.name_ko, cd.name_en, coalesce(cd.price_won, 0),
           cd.contains, cd.may_contain, 0, c.checked_on
    from _chain_targets t
    cross join public.chain_menu_dishes cd
    where cd.chain_id = c.chain_id
    on conflict (id) do nothing;
    get diagnostics v_dishes = row_count;

    update public.restaurants r set sources = array_append(r.sources, 'chain menu (official site)')
    from _chain_targets t
    where r.id = t.restaurant_id and not ('chain menu (official site)' = any (r.sources));

    chain_id := c.chain_id; restaurants_matched := v_matched; restaurants_filled := v_filled; dishes_added := v_dishes;
    return next;
  end loop;
end;
$$;
-- Only the team runs this from the SQL editor.
revoke all on function public.apply_chain_menus(text) from public, anon, authenticated;

commit;
